// TODO: Replace dotenv.parse with `import { parseEnv } from 'node:util'` once the CLI is on Node 22+
import fs from 'node:fs';
import path from 'node:path';
import dotenv from 'dotenv';
import { getSecretsInContext, PRIVATE_APP_ACCESS_TOKEN } from './constants.js';
import { PrivateAppUserTokenUnavailableError, tokenUnavailableHint, } from './errors.js';
import { PrivateAppUserTokenManager } from './services/PrivateAppUserTokenManager.js';
function getEnvPath(srcDir) {
    const mode = process.env.NODE_ENV;
    return (mode
        ? [`.env.${mode}.local`, '.env.local', `.env.${mode}`, '.env']
        : ['.env.local', '.env'])
        .map((fileName) => path.join(srcDir, fileName))
        .find(fs.existsSync);
}
export function setProperTokenInSecrets(secrets, logger, privateAppUserToken, options) {
    const accessTokenKey = options?.accessTokenKey ?? PRIVATE_APP_ACCESS_TOKEN;
    const privateAppToken = secrets?.[accessTokenKey];
    if (!privateAppUserToken) {
        if (!privateAppToken && options?.installThrowingGetter) {
            return installTokenUnavailableGetter(secrets, options.accountId, logger, accessTokenKey);
        }
        return secrets;
    }
    if (privateAppToken && privateAppUserToken) {
        /*
         * Make sure that the privateAppUserToken has all the scopes from the privateAppToken.
         * If they do, suggest that they remove the privateAppToken from the environment file.
         */
        if (PrivateAppUserTokenManager.doesUserTokenContainAppTokenScopes(privateAppUserToken)) {
            logger.info(`The private app user token was overridden by the ${accessTokenKey} in the environment file. For local development, you no longer need a ${accessTokenKey} in the environment file. You can safely remove it.`);
        }
        // privateAppToken it's already in the secrets and it takes precedence. just return
        return secrets;
    }
    // has only one of the tokens. Set the proper one in the secrets taking into account that privateAppToken takes precedence
    const result = { ...secrets };
    const theToken = privateAppToken ?? privateAppUserToken?.userTokenKey;
    result[accessTokenKey] = theToken;
    process.env[accessTokenKey] = theToken;
    return result;
}
function installTokenUnavailableGetter(secrets, accountId, logger, accessTokenKey) {
    /*
     * When a serverless function reads the access-token env var while running on
     * a test/sandbox account with no token configured, we want a clear, actionable
     * error at the read site — not the confusing HubSpot 401 that comes back when
     * the function passes an undefined token to the HubSpot API.
     *
     * Node's real `process.env` is a Proxy that only accepts data descriptors, so
     * we swap it for a plain-object copy before defining an accessor. The executor
     * already snapshots `process.env` at the top of each invocation and restores
     * it on every exit path, so this identity swap is unwound automatically when
     * the function finishes.
     */
    process.env = { ...process.env };
    Object.defineProperty(process.env, accessTokenKey, {
        configurable: true,
        enumerable: true,
        get() {
            /*
             * Log before throwing so the hint is visible in the dev-server terminal
             * even when the developer's function wraps the read in a try/catch that
             * doesn't surface the caught error (e.g. the HubSpot docs sample for
             * contact-create extracts `error.response.data.message`, which doesn't
             * exist on our typed error).
             */
            const hint = tokenUnavailableHint(accessTokenKey);
            logger.error(`Cannot obtain a private-app access token for accountId=${accountId}. ${hint}`);
            throw new PrivateAppUserTokenUnavailableError(`Cannot obtain a private-app access token for accountId=${accountId}.`, { hint });
        },
    });
    return secrets;
}
export function loadSecrets(srcDir, accessTokenKey = PRIVATE_APP_ACCESS_TOKEN) {
    const envPath = getEnvPath(srcDir);
    if (envPath) {
        try {
            const content = fs.readFileSync(envPath, 'utf8');
            Object.assign(process.env, dotenv.parse(content));
        }
        catch (error) {
            // Silently ignore read errors to match dotenv's quiet behavior
        }
    }
    const secrets = {};
    getSecretsInContext(accessTokenKey).forEach((secretName) => {
        const secretValue = process.env[secretName];
        if (typeof secretValue === 'string') {
            secrets[secretName] = secretValue;
        }
    });
    return secrets;
}
